tool_schemas.implementation:
def sendBulkMail(mail_account_id, subject, bulk_payload, from_email=None, from_name=None, template=None, body_text=None, body_html=None, attachment_refs=None, to=None, cc=None, bcc=None, scheduled_for=None, related_in_reply_to_email_id=None, **_extra):
    import json, os, datetime, time, re, random, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "sendBulkMail"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    _C32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        ts = ms
        chars = []
        for _ in range(10):
            chars.append(_C32[ts & 31])
            ts //= 32
        chars = chars[::-1]
        rand = random.getrandbits(80)
        rchars = []
        for _ in range(16):
            rchars.append(_C32[rand & 31])
            rand //= 32
        rchars = rchars[::-1]
        return f"{prefix}_" + "".join(chars + rchars)

    def _ensure_list_str(v, field):
        if v is None:
            return True, None
        if not isinstance(v, list) or not all(isinstance(x, str) for x in v):
            return False, _err("VALIDATION_ERROR", f"{field} must be an array of strings.", field=field)
        return True, None

    def _emailish(v):
        # Relaxed validation: accept any string containing '@' with no spaces.
        if not isinstance(v, str):
            return False
        s = v.strip()
        if not s or " " in s:
            return False
        if "@" not in s:
            return False
        return True

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {
            "id": rid,
            "endpoint": endpoint,
            "mail_account_id": mail_acct,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
        }
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _quota_check_and_consume(account_id, recipients_count):
        # Implementation-level caps (lightweight): 2500/day and 100 req/min per account.
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        day_ago = now - datetime.timedelta(days=1)
        min_ago = now - datetime.timedelta(minutes=1)

        sends_24h = 0
        reqs_1m = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("mail_account_id") != account_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            dt = _parse_dt(ts)
            if dt is None:
                continue
            if dt >= min_ago:
                reqs_1m += 1
            # Count only send* endpoints as "send volume"
            if dt >= day_ago and isinstance(r.get("endpoint"), str) and r.get("endpoint") in ("sendMail", "sendSimpleMail", "sendHtmlMail", "sendBulkMail") and r.get("status") in ("OK", "CREATED", "QUEUED", "SENT"):
                # For bulk, we don't have recipients on the request log; count 1 job as 1 message unit.
                sends_24h += 1

        if reqs_1m >= 100:
            return _err("RATE_LIMIT", "Rate limit exceeded for this mail account (max 100 requests/min).")
        if sends_24h + 1 > 2500:
            return _err("QUOTA_EXCEEDED", "Daily send quota exceeded for this mail account (max 2500 send jobs/day).")
        return None

    # Validate requireds (relaxed patterns; accept datastore and caller strings)
    if not isinstance(mail_account_id, str) or not mail_account_id.startswith("mail_acct_"):
        _log("VALIDATION_ERROR", None, {"field": "mail_account_id"})
        return _err("VALIDATION_ERROR", "Invalid mail_account_id.", field="mail_account_id")
    if not isinstance(subject, str) or not subject.strip():
        _log("VALIDATION_ERROR", mail_account_id, {"field": "subject"})
        return _err("VALIDATION_ERROR", "subject is required.", field="subject")
    if not isinstance(bulk_payload, dict):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "bulk_payload"})
        return _err("VALIDATION_ERROR", "bulk_payload must be an object.", field="bulk_payload")

    for field, val in (("to", to), ("cc", cc), ("bcc", bcc), ("attachment_refs", attachment_refs)):
        ok, e = _ensure_list_str(val, field)
        if not ok:
            _log("VALIDATION_ERROR", mail_account_id, {"field": field})
            return e

    if from_email is not None and (not isinstance(from_email, str) or not from_email.strip()):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "from_email"})
        return _err("VALIDATION_ERROR", "from_email must be a non-empty string when provided.", field="from_email")
    if from_name is not None and (not isinstance(from_name, str) or not from_name.strip()):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "from_name"})
        return _err("VALIDATION_ERROR", "from_name must be a non-empty string when provided.", field="from_name")
    if template is not None and not isinstance(template, str):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "template"})
        return _err("VALIDATION_ERROR", "template must be a string.", field="template")
    if body_text is not None and not isinstance(body_text, str):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "body_text"})
        return _err("VALIDATION_ERROR", "body_text must be a string.", field="body_text")
    if body_html is not None and not isinstance(body_html, str):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "body_html"})
        return _err("VALIDATION_ERROR", "body_html must be a string.", field="body_html")

    sch_dt = None
    if scheduled_for is not None:
        if not isinstance(scheduled_for, str):
            _log("VALIDATION_ERROR", mail_account_id, {"field": "scheduled_for"})
            return _err("VALIDATION_ERROR", "scheduled_for must be an ISO date-time string.", field="scheduled_for")
        sch_dt = _parse_dt(scheduled_for)
        if sch_dt is None:
            _log("VALIDATION_ERROR", mail_account_id, {"field": "scheduled_for"})
            return _err("VALIDATION_ERROR", "scheduled_for is not a valid date-time.", field="scheduled_for")
        if sch_dt <= _now():
            _log("VALIDATION_ERROR", mail_account_id, {"field": "scheduled_for"})
            return _err("VALIDATION_ERROR", "scheduled_for must be in the future.", field="scheduled_for")

    if related_in_reply_to_email_id is not None:
        if not isinstance(related_in_reply_to_email_id, str) or not related_in_reply_to_email_id.startswith("mail_msg_"):
            _log("VALIDATION_ERROR", mail_account_id, {"field": "related_in_reply_to_email_id"})
            return _err("VALIDATION_ERROR", "Invalid related_in_reply_to_email_id.", field="related_in_reply_to_email_id")

    # Resolve account (must exist; prefer active, but accept non-active if it's the referenced one)
    accounts = _load("mail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == mail_account_id:
            acct = a
            break
    if acct is None:
        _log("NOT_FOUND", mail_account_id, {"field": "mail_account_id"})
        return _err("NOT_FOUND", "Mail account not found.", field="mail_account_id")
    if acct.get("status") != "active":
        _log("CONFLICT", mail_account_id, {"rule": "mail_accounts.status must be active to send"})
        return _err("CONFLICT", "Mail account is not active; cannot send.", rule="mail_accounts.status must be active to send")

    # Optional reply linkage existence
    if related_in_reply_to_email_id is not None:
        emails = _load("emails.json")
        if not isinstance(emails, list):
            emails = []
        found = None
        for e in emails:
            if isinstance(e, dict) and e.get("id") == related_in_reply_to_email_id:
                found = e
                break
        if found is None:
            _log("NOT_FOUND", mail_account_id, {"field": "related_in_reply_to_email_id"})
            return _err("NOT_FOUND", "related_in_reply_to_email_id not found.", field="related_in_reply_to_email_id")
        if found.get("mail_account_id") != mail_account_id:
            _log("UNAUTHORIZED", mail_account_id, {"field": "related_in_reply_to_email_id"})
            return _err("UNAUTHORIZED", "You don’t have access to the referenced message.", field="related_in_reply_to_email_id")

    # Bulk limits: <=1000 recipients (from bulk_payload or to list) and <=1MB payload (JSON)
    try:
        payload_bytes = len(json.dumps(bulk_payload, ensure_ascii=False).encode("utf-8"))
    except (TypeError, ValueError):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "bulk_payload"})
        return _err("VALIDATION_ERROR", "bulk_payload must be JSON-serializable.", field="bulk_payload")
    if payload_bytes > 1024 * 1024:
        _log("VALIDATION_ERROR", mail_account_id, {"rule": "bulk_payload size <= 1MB"})
        return _err("VALIDATION_ERROR", "bulk_payload too large (max 1MB).", rule="bulk_payload size <= 1MB")

    def _count_recipients_in_payload(p):
        # Heuristic: if payload has a list under common keys, count it.
        if not isinstance(p, dict):
            return 0
        for k in ("recipients", "to", "personalizations", "messages"):
            v = p.get(k)
            if isinstance(v, list):
                return len(v)
        return 0

    recipients_est = _count_recipients_in_payload(bulk_payload)
    if recipients_est == 0 and isinstance(to, list):
        recipients_est = len(to)
    if recipients_est > 1000:
        _log("VALIDATION_ERROR", mail_account_id, {"rule": "max recipients per bulk job <= 1000"})
        return _err("VALIDATION_ERROR", "Too many recipients for one bulk job (max 1000).", rule="max recipients per bulk job <= 1000")

    # Validate addresses lightly (do not reject paths/handles mistakenly passed)
    for field, lst in (("to", to), ("cc", cc), ("bcc", bcc)):
        if lst is None:
            continue
        bad = [x for x in lst if not _emailish(x)]
        if bad:
            _log("VALIDATION_ERROR", mail_account_id, {"field": field})
            return _err("VALIDATION_ERROR", f"One or more {field} recipients are malformed.", field=field, invalid=bad)

    # Quota/rate checks (based on request_logs)
    qerr = _quota_check_and_consume(mail_account_id, recipients_est)
    if qerr:
        _log(qerr["error"]["code"], mail_account_id)
        return qerr

    jobs = _load("mail_send_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    now_iso = _now_iso()
    job_id = _new_id("mail_job")
    job = {
        "id": job_id,
        "mail_account_id": mail_account_id,
        "job_type": "sendBulkMail",
        "template": template,
        "from_email": from_email if from_email is not None else acct.get("email_address"),
        "from_name": from_name if from_name is not None else (acct.get("default_from_name") or acct.get("display_name")),
        "to": to,
        "cc": cc,
        "bcc": bcc,
        "subject": subject,
        "body_text": body_text,
        "body_html": body_html,
        "attachment_refs": attachment_refs,
        "bulk_payload": bulk_payload,
        "related_in_reply_to_email_id": related_in_reply_to_email_id,
        "provider_outbound_message_id": None,
        "created_email_id": None,
        "attempt_count": 0,
        "last_error": None,
        "scheduled_for": scheduled_for,
        "sent_at": None,
        "status": "queued",
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # If scheduled_for, keep queued (vendor text says queued/scheduled; schema lacks scheduled, so queued)
    # Execute lifecycle: queued -> sending -> sent/failed
    # For offline behavior, we simulate immediate send unless scheduled.
    if sch_dt is None:
        # queued -> sending
        job["status"] = "sending"
        job["attempt_count"] = 1
        job["updated_at"] = _now_iso()

        # Attachment size enforcement (best-effort: if ref points to known attachment, enforce <=25MB)
        MAX_ATT_BYTES = 25 * 1024 * 1024
        if attachment_refs:
            atts = _load("email_attachments.json")
            if not isinstance(atts, list):
                atts = []
            # If refs are ids of known attachments, enforce size.
            for ref in attachment_refs:
                if isinstance(ref, str) and ref.startswith("mail_att_"):
                    for a in atts:
                        if isinstance(a, dict) and a.get("id") == ref:
                            sz = a.get("size_bytes")
                            if isinstance(sz, int) and sz > MAX_ATT_BYTES:
                                job["status"] = "failed"
                                job["last_error"] = f"Attachment {ref} exceeds 25MB limit."
                                job["updated_at"] = _now_iso()
                            break
                if job["status"] == "failed":
                    break

        if job["status"] != "failed":
            # Simulate provider accept
            job["provider_outbound_message_id"] = "prov_" + hashlib.sha256((job_id + "|" + now_iso).encode("utf-8")).hexdigest()[:24]
            job["status"] = "sent"
            job["sent_at"] = _now_iso()
            job["updated_at"] = job["sent_at"]

    jobs.append(job)
    _save("mail_send_jobs.json", jobs)

    _log("OK", mail_account_id, {"job_id": job_id, "status": job["status"]})
    return {"job": job}

def sendMail(mail_account_id, to, subject, from_email=None, from_name=None, cc=None, bcc=None, body_text=None, body_html=None, attachment_refs=None, scheduled_for=None, related_in_reply_to_email_id=None, **_extra):
    import json, os, datetime, time, random, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "sendMail"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    _C32 = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
    def _new_id(prefix):
        ms = int(time.time() * 1000)
        ts = ms
        chars = []
        for _ in range(10):
            chars.append(_C32[ts & 31])
            ts //= 32
        chars = chars[::-1]
        rand = random.getrandbits(80)
        rchars = []
        for _ in range(16):
            rchars.append(_C32[rand & 31])
            rand //= 32
        rchars = rchars[::-1]
        return f"{prefix}_" + "".join(chars + rchars)

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _as_list(x, field):
        if x is None:
            return []
        if not isinstance(x, list):
            return None
        out = []
        for v in x:
            if not isinstance(v, str) or not v.strip():
                return None
            out.append(v.strip())
        return out

    def _emailish(s):
        if not isinstance(s, str):
            return False
        ss = s.strip()
        if not ss or "@" not in ss or ss.startswith("@") or ss.endswith("@"):
            return False
        if " " in ss:
            return False
        return True

    # Validate inputs
    if not isinstance(mail_account_id, str) or not mail_account_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "mail_account_id"})
        return _err("VALIDATION_ERROR", "mail_account_id is required.", field="mail_account_id")

    if not isinstance(to, list) or len(to) < 1:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "to"})
        return _err("VALIDATION_ERROR", "to must be a non-empty array.", field="to")

    to_list = _as_list(to, "to")
    if to_list is None:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "to"})
        return _err("VALIDATION_ERROR", "to must be an array of non-empty strings.", field="to")

    cc_list = _as_list(cc, "cc")
    if cc is not None and cc_list is None:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "cc"})
        return _err("VALIDATION_ERROR", "cc must be an array of non-empty strings when provided.", field="cc")

    bcc_list = _as_list(bcc, "bcc")
    if bcc is not None and bcc_list is None:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "bcc"})
        return _err("VALIDATION_ERROR", "bcc must be an array of non-empty strings when provided.", field="bcc")

    if not isinstance(subject, str) or not subject.strip():
        _log("VALIDATION_ERROR", mail_account_id, {"field": "subject"})
        return _err("VALIDATION_ERROR", "subject is required.", field="subject")

    if from_email is not None and (not isinstance(from_email, str) or not from_email.strip()):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "from_email"})
        return _err("VALIDATION_ERROR", "from_email must be a non-empty string when provided.", field="from_email")
    if from_name is not None and (not isinstance(from_name, str) or not from_name.strip()):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "from_name"})
        return _err("VALIDATION_ERROR", "from_name must be a non-empty string when provided.", field="from_name")

    if body_text is not None and not isinstance(body_text, str):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "body_text"})
        return _err("VALIDATION_ERROR", "body_text must be a string when provided.", field="body_text")
    if body_html is not None and not isinstance(body_html, str):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "body_html"})
        return _err("VALIDATION_ERROR", "body_html must be a string when provided.", field="body_html")

    att_list = _as_list(attachment_refs, "attachment_refs")
    if attachment_refs is not None and att_list is None:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "attachment_refs"})
        return _err("VALIDATION_ERROR", "attachment_refs must be an array of non-empty strings when provided.", field="attachment_refs")

    sch_dt = None
    if scheduled_for is not None:
        sch_dt = _parse_dt(scheduled_for)
        if sch_dt is None:
            _log("VALIDATION_ERROR", mail_account_id, {"field": "scheduled_for"})
            return _err("VALIDATION_ERROR", "scheduled_for must be a valid RFC3339 date-time string when provided.", field="scheduled_for")

    if related_in_reply_to_email_id is not None and (not isinstance(related_in_reply_to_email_id, str) or not related_in_reply_to_email_id.strip()):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "related_in_reply_to_email_id"})
        return _err("VALIDATION_ERROR", "related_in_reply_to_email_id must be a string when provided.", field="related_in_reply_to_email_id")

    # Be permissive about recipient "email validity": reject only obvious non-strings/empties; allow IDs/URIs if passed.
    # However if something looks like an email, lightly validate.
    for field_name, lst in (("to", to_list), ("cc", cc_list), ("bcc", bcc_list)):
        for v in lst:
            if "@" in v and not _emailish(v):
                _log("VALIDATION_ERROR", mail_account_id, {"field": field_name, "value": v})
                return _err("VALIDATION_ERROR", f"{field_name} contains an invalid email address.", field=field_name, value=v)

    # Load and verify mail_account
    accounts = _load("mail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if isinstance(a, dict) and a.get("id") == mail_account_id:
            acct = a
            break
    if acct is None:
        _log("NOT_FOUND", mail_account_id, {"field": "mail_account_id"})
        return _err("NOT_FOUND", "Mail account not found.", field="mail_account_id")

    if acct.get("status") != "active":
        _log("INVALID_TRANSITION", mail_account_id, {"rule": "mail_account.status must be active", "status": acct.get("status")})
        return _err("INVALID_TRANSITION", "Mail account is not active.", status=acct.get("status"), rule="mail_account.status must be active")

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    if related_in_reply_to_email_id is not None:
        found_related = None
        for e in emails:
            if isinstance(e, dict) and e.get("id") == related_in_reply_to_email_id:
                found_related = e
                break
        if found_related is None:
            _log("NOT_FOUND", mail_account_id, {"field": "related_in_reply_to_email_id"})
            return _err("NOT_FOUND", "Related email not found.", field="related_in_reply_to_email_id")
        if found_related.get("mail_account_id") != mail_account_id:
            _log("UNAUTHORIZED", mail_account_id, {"rule": "related email must belong to same mail_account_id"})
            return _err("UNAUTHORIZED", "You don’t have access to the related email.", rule="related email must belong to same mail_account_id")

    # Quota/rate limit (implementation-level): cap sends/day per account (e.g. 500/day) using request_logs
    # Every call logs; only count successful sends (status='sent') for quota.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now = _now()
    day_start = now.replace(hour=0, minute=0, second=0)
    sent_today = 0
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("endpoint") not in ("sendMail", "sendSimpleMail", "sendHtmlMail", "sendBulkMail"):
            continue
        if r.get("mail_account_id") != mail_account_id:
            continue
        if r.get("status") != "sent":
            continue
        ts = r.get("timestamp")
        dt = _parse_dt(ts) if isinstance(ts, str) else None
        if dt is not None and dt >= day_start and dt <= now:
            sent_today += 1
    DAILY_LIMIT = 500
    if sent_today >= DAILY_LIMIT:
        _log("QUOTA_EXCEEDED", mail_account_id, {"rule": "daily send limit", "limit": DAILY_LIMIT})
        return _err("QUOTA_EXCEEDED", "Daily send quota exceeded for this mail account.", rule="daily send limit", limit=DAILY_LIMIT)

    # Attachment size limit: if attachment_ref looks like a local path and exists, enforce <= 25MB
    MAX_ATTACHMENT_BYTES = 25 * 1024 * 1024
    if att_list:
        for ref in att_list:
            try:
                if isinstance(ref, str) and ref.startswith("/"):
                    p = ref
                    if os.path.exists(p) and os.path.isfile(p):
                        sz = os.path.getsize(p)
                        if sz > MAX_ATTACHMENT_BYTES:
                            # Create job as failed per rule? Spec says violations must fail send job with status='failed'
                            pass
            except OSError:
                # ignore non-stat'able refs
                pass

    jobs = _load("mail_send_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    now_iso = _now_iso()
    job_id = _new_id("mail_job")
    job = {
        "id": job_id,
        "mail_account_id": mail_account_id,
        "job_type": "sendMail",
        "template": None,
        "from_email": (from_email.strip() if isinstance(from_email, str) and from_email.strip() else acct.get("email_address")),
        "from_name": (from_name.strip() if isinstance(from_name, str) and from_name.strip() else acct.get("default_from_name") or acct.get("display_name")),
        "to": to_list,
        "cc": cc_list if cc_list else None,
        "bcc": bcc_list if bcc_list else None,
        "subject": subject,
        "body_text": body_text,
        "body_html": body_html,
        "attachment_refs": att_list if att_list else None,
        "bulk_payload": None,
        "related_in_reply_to_email_id": related_in_reply_to_email_id,
        "provider_outbound_message_id": None,
        "created_email_id": None,
        "attempt_count": 0,
        "last_error": None,
        "scheduled_for": (sch_dt.replace(microsecond=0).isoformat().replace("+00:00", "Z") if sch_dt is not None else None),
        "sent_at": None,
        "status": "queued",
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # If attachment size violation detected, mark failed immediately but still persist the job
    size_violation = None
    if att_list:
        for ref in att_list:
            try:
                if isinstance(ref, str) and ref.startswith("/"):
                    if os.path.exists(ref) and os.path.isfile(ref):
                        sz = os.path.getsize(ref)
                        if sz > MAX_ATTACHMENT_BYTES:
                            size_violation = {"ref": ref, "size_bytes": sz, "limit_bytes": MAX_ATTACHMENT_BYTES}
                            break
            except OSError:
                continue

    jobs.append(job)
    _save("mail_send_jobs.json", jobs)

    # Transition queued -> sending -> sent/failed (synchronous simulation)
    # Respect scheduled_for: if in future, keep queued and return.
    if sch_dt is not None and sch_dt > now:
        _log("queued", mail_account_id, {"job_id": job_id})
        return {"job": job}

    # Update to sending
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "sending"
            j["updated_at"] = _now_iso()
            j["attempt_count"] = int(j.get("attempt_count") or 0) + 1
            break
    _save("mail_send_jobs.json", jobs)

    if size_violation is not None:
        for j in jobs:
            if isinstance(j, dict) and j.get("id") == job_id:
                j["status"] = "failed"
                j["last_error"] = f"Attachment exceeds size limit: {size_violation['ref']} ({size_violation['size_bytes']} bytes > {size_violation['limit_bytes']} bytes)"
                j["updated_at"] = _now_iso()
                break
        _save("mail_send_jobs.json", jobs)
        # log as failed (quota dynamics)
        _log("failed", mail_account_id, {"job_id": job_id, "rule": "attachment size limit"})
        # return persisted job
        for j in jobs:
            if isinstance(j, dict) and j.get("id") == job_id:
                return {"job": j}
        return _err("NOT_FOUND", "Send job not found after creation.", field="job_id")

    # "Send" success: set sent_at and provider_outbound_message_id
    provider_outbound_message_id = "prov_" + hashlib.sha256(f"{job_id}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    sent_iso = _now_iso()
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "sent"
            j["sent_at"] = sent_iso
            j["provider_outbound_message_id"] = provider_outbound_message_id
            j["updated_at"] = sent_iso
            break
    _save("mail_send_jobs.json", jobs)

    _log("sent", mail_account_id, {"job_id": job_id})
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            return {"job": j}
    return _err("NOT_FOUND", "Send job not found after creation.", field="job_id")

