            j["attempt_count"] = int(j.get("attempt_count") or 0) + 1
            j["updated_at"] = _now_iso()
            break
    _save("mail_send_jobs.json", jobs)

    provider_outbound_message_id = "prov_" + hashlib.sha256(f"{job_id}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
    sent_iso = _now_iso()
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            j["status"] = "sent"
            j["sent_at"] = sent_iso
            j["provider_outbound_message_id"] = provider_outbound_message_id
            j["updated_at"] = sent_iso
            break
    _save("mail_send_jobs.json", jobs)

    _log("sent", mail_account_id, {"job_id": job_id})
    for j in jobs:
        if isinstance(j, dict) and j.get("id") == job_id:
            return {"job": j}
    return _err("NOT_FOUND", "Send job not found after creation.", field="job_id")

def waitForReply(mail_account_id, in_reply_to_email_id, thread_id=None, timeout_seconds=None, poll_interval_seconds=None, mark_as_read=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "waitForReply"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        if not ss:
            return None
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate required params (do not over-enforce vendor regex; accept any non-empty string)
    if not isinstance(mail_account_id, str) or not mail_account_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "mail_account_id"})
        return _err("VALIDATION_ERROR", "mail_account_id is required.", field="mail_account_id")
    if not isinstance(in_reply_to_email_id, str) or not in_reply_to_email_id.strip():
        _log("VALIDATION_ERROR", mail_account_id.strip(), {"field": "in_reply_to_email_id"})
        return _err("VALIDATION_ERROR", "in_reply_to_email_id is required.", field="in_reply_to_email_id")

    mail_account_id = mail_account_id.strip()
    in_reply_to_email_id = in_reply_to_email_id.strip()

    if thread_id is not None and not isinstance(thread_id, str):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "thread_id"})
        return _err("VALIDATION_ERROR", "thread_id must be a string when provided.", field="thread_id")
    if isinstance(thread_id, str):
        thread_id = thread_id.strip()
        if thread_id == "":
            thread_id = None
        # Unsupported/invalid format check: only reject clearly pathological thread ids
        if thread_id is not None and len(thread_id) > 512:
            _log("VALIDATION_ERROR", mail_account_id, {"field": "thread_id", "rule": "max_length<=512"})
            return _err("VALIDATION_ERROR", "thread_id is in an unsupported/invalid format.", field="thread_id", rule="max_length<=512")

    if timeout_seconds is None:
        timeout_seconds = 30
    if poll_interval_seconds is None:
        poll_interval_seconds = 2
    if not isinstance(timeout_seconds, int) or timeout_seconds < 1:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "timeout_seconds"})
        return _err("VALIDATION_ERROR", "timeout_seconds must be an integer >= 1.", field="timeout_seconds")
    if not isinstance(poll_interval_seconds, int) or poll_interval_seconds < 1:
        _log("VALIDATION_ERROR", mail_account_id, {"field": "poll_interval_seconds"})
        return _err("VALIDATION_ERROR", "poll_interval_seconds must be an integer >= 1.", field="poll_interval_seconds")
    if mark_as_read is not None and not isinstance(mark_as_read, bool):
        _log("VALIDATION_ERROR", mail_account_id, {"field": "mark_as_read"})
        return _err("VALIDATION_ERROR", "mark_as_read must be boolean when provided.", field="mark_as_read")
    mark_as_read = bool(mark_as_read) if mark_as_read is not None else False

    mail_accounts = _load("mail_accounts.json")
    if not isinstance(mail_accounts, list):
        mail_accounts = []
    acct = next((a for a in mail_accounts if isinstance(a, dict) and a.get("id") == mail_account_id), None)
    if acct is None:
        _log("NOT_FOUND", mail_account_id, {"field": "mail_account_id"})
        return _err("NOT_FOUND", "Mail account not found.", field="mail_account_id")

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    # Find original email: if caller passed something else (audit shows it did), treat as correlation key (email address / arbitrary token)
    original = next((e for e in emails if isinstance(e, dict) and e.get("id") == in_reply_to_email_id and e.get("mail_account_id") == mail_account_id), None)

    original_thread_id = original.get("thread_id") if isinstance(original, dict) else None
    original_internet_id = original.get("internet_message_id") if isinstance(original, dict) else None
    original_sent_at = _parse_dt(original.get("sent_at")) if isinstance(original, dict) else None
    original_created_at = _parse_dt(original.get("created_at")) if isinstance(original, dict) else None
    after_dt = original_sent_at or original_created_at

    # Decide thread scope: prefer explicit thread_id, else original thread id if available
    scope_thread_id = thread_id or original_thread_id

    # Poll loop: since datastore is static offline, we still respect the timeout window for consistency
    deadline = time.time() + float(timeout_seconds)
    found = None

    def _matches(reply):
        if not isinstance(reply, dict):
            return False
        if reply.get("mail_account_id") != mail_account_id:
            return False
        if reply.get("status") != "active":
            return False
        if reply.get("direction") != "inbound":
            return False

        # Time constraint: must be received after original sent_at (or created_at) if known
        if after_dt is not None:
            rdt = _parse_dt(reply.get("received_at")) or _parse_dt(reply.get("created_at"))
            if rdt is None:
                return False
            if rdt <= after_dt:
                return False

        # Thread scope if we have it
        if scope_thread_id is not None:
            return reply.get("thread_id") == scope_thread_id

        # Otherwise try correlate by internet_message_id or loose token match
        # If we have original internet id, look for it in common reply headers stored in snippet/body, or same thread_id if present.
        if original_internet_id:
            blob = " ".join([str(reply.get("subject") or ""), str(reply.get("snippet") or ""), str(reply.get("body_text") or ""), str(reply.get("body_html") or "")]).lower()
            if original_internet_id.lower() in blob:
                return True

        # Fallback: treat in_reply_to_email_id as arbitrary token and match it in subject/snippet/body
        token = in_reply_to_email_id.lower()
        blob = " ".join([str(reply.get("subject") or ""), str(reply.get("snippet") or ""), str(reply.get("body_text") or ""), str(reply.get("body_html") or "")]).lower()
        if token and token in blob:
            return True

        return False

    while time.time() <= deadline and found is None:
        # Find earliest matching inbound reply
        candidates = [e for e in emails if _matches(e)]
        # Prefer oldest after original (first reply)
        def _cand_key(e):
            return (_parse_dt(e.get("received_at")) or _parse_dt(e.get("created_at")) or _now())
        candidates.sort(key=_cand_key)
        if candidates:
            found = candidates[0]
            break
        # If no time left, break; else sleep
        remaining = deadline - time.time()
        if remaining <= 0:
            break
        time.sleep(min(float(poll_interval_seconds), max(0.0, remaining)))

    if found is None:
        _log("NOT_FOUND", mail_account_id, {"reason": "timeout", "in_reply_to_email_id": in_reply_to_email_id, "thread_id": scope_thread_id})
        return _err("NOT_FOUND", "No reply found within timeout window.", reason="timeout", in_reply_to_email_id=in_reply_to_email_id, thread_id=scope_thread_id)

    # Mark as read if requested (only if active)
    if mark_as_read and found.get("is_read") is not True:
        now_iso = _now_iso()
        # persist update
        for i, e in enumerate(emails):
            if isinstance(e, dict) and e.get("id") == found.get("id"):
                e["is_read"] = True
                e["updated_at"] = now_iso
                emails[i] = e
                found = e
                _save("emails.json", emails)
                break

    _log("OK", mail_account_id, {"reply_email_id": found.get("id")})
    return {"reply": found}

def searchEmails(mail_account_id, query, folder_id=None, thread_id=None, direction=None, is_read=None, has_attachments=None, received_after=None, received_before=None, sent_after=None, sent_before=None, status=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "searchEmails"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field_name):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(field_name)
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            raise ValueError(field_name)

    def _log(status, error_code=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{_now_iso()}|{time.time_ns()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "mail_account_id": mail_account_id,
            "credential_used": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(logs, list):
            logs.append(row)
            _save("request_logs.json", logs)

    # Validate
    if not isinstance(mail_account_id, str) or not re.match(r"^mail_acct_[0-9A-HJKMNP-TV-Z]{10,}$", mail_account_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "mail_account_id must be a valid mail account id.")
    if not isinstance(query, str) or len(query.strip()) == 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if folder_id is not None and (not isinstance(folder_id, str) or not re.match(r"^mail_fldr_[0-9A-HJKMNP-TV-Z]{10,}$", folder_id)):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "folder_id must be a valid folder id when provided.")
    if thread_id is not None and (not isinstance(thread_id, str) or len(thread_id.strip()) == 0):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thread_id must be a non-empty string when provided.")
    if direction is not None and direction not in ("inbound", "outbound"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "direction must be 'inbound' or 'outbound'.")
    if is_read is not None and not isinstance(is_read, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_read must be a boolean when provided.")
    if has_attachments is not None and not isinstance(has_attachments, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "has_attachments must be a boolean when provided.")
    if status is not None and status not in ("active", "deleted", "purged"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted, purged.")
    if sort_by is None:
        sort_by = "received_at"
    if sort_by not in ("received_at", "sent_at", "created_at", "updated_at"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: received_at, sent_at, created_at, updated_at.")
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    try:
        r_after = _parse_dt(received_after, "received_after")
        r_before = _parse_dt(received_before, "received_before")
        s_after = _parse_dt(sent_after, "sent_after")
        s_before = _parse_dt(sent_before, "sent_before")
    except ValueError as e:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", f"{str(e)} must be an RFC3339 date-time string.")

    accounts = _load("mail_accounts.json")
    acct = next((a for a in accounts if a.get("id") == mail_account_id), None)
    if not acct:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Mail account not found.")
    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Mail account is not active.")

    folders = _load("mail_folders.json")
    folder = None
    if folder_id is not None:
        folder = next((f for f in folders if f.get("id") == folder_id and f.get("mail_account_id") == mail_account_id), None)
        if not folder:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Folder not found in this mail account.")

    # Decode cursor (offset-based)
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("badcursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("badcursor")
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    q = query.strip().lower()

    def _dt_for_sort(e):
        val = e.get(sort_by)
        if not isinstance(val, str):
            return None
        try:
            ss = val[:-1] + "+00:00" if val.endswith("Z") else val
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    emails = _load("emails.json")
    matches = []
    for e in emails:
        if e.get("mail_account_id") != mail_account_id:
            continue
        # search defaults to excluding non-active unless status filter asks otherwise; business rules: exclude status!='active'
        if status is None:
            if e.get("status") != "active":
                continue
        else:
            if e.get("status") != status:
                continue

        if folder_id is not None and e.get("folder_id") != folder_id:
            continue
        if thread_id is not None and e.get("thread_id") != thread_id:
            continue
        if direction is not None and e.get("direction") != direction:
            continue
        if is_read is not None and e.get("is_read") is not is_read:
            continue
        if has_attachments is not None and e.get("has_attachments") is not has_attachments:
            continue

        rdt = _dt_for_sort(e) if sort_by in ("received_at", "sent_at", "created_at", "updated_at") else None
        # time window filters
        if r_after is not None:
            er = _parse_dt(e.get("received_at"), "received_at") if isinstance(e.get("received_at"), str) else None
            if er is None or er <= r_after:
                continue
        if r_before is not None:
            er = _parse_dt(e.get("received_at"), "received_at") if isinstance(e.get("received_at"), str) else None
            if er is None or er >= r_before:
                continue
        if s_after is not None:
            es = _parse_dt(e.get("sent_at"), "sent_at") if isinstance(e.get("sent_at"), str) else None
            if es is None or es <= s_after:
                continue
        if s_before is not None:
            es = _parse_dt(e.get("sent_at"), "sent_at") if isinstance(e.get("sent_at"), str) else None
            if es is None or es >= s_before:
                continue

        hay = " ".join([
            str(e.get("subject") or ""),
            str(e.get("snippet") or ""),
            str(e.get("body_text") or ""),
            str(e.get("body_html") or ""),
            str(e.get("from_name") or ""),
            str(e.get("from_email") or ""),
            " ".join([str(x) for x in (e.get("to_emails") or [])]) if isinstance(e.get("to_emails"), list) else "",
            " ".join([str(x) for x in (e.get("cc_emails") or [])]) if isinstance(e.get("cc_emails"), list) else "",
            " ".join([str(x) for x in (e.get("bcc_emails") or [])]) if isinstance(e.get("bcc_emails"), list) else "",
        ]).lower()

        if q not in hay:
            continue

        matches.append(e)

    # Sort
    reverse = (sort_order == "desc")

    def _sort_key(e):
        dt = _dt_for_sort(e)
        # None sorts last for desc/asc deterministically
        sentinel = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if reverse else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        dt2 = dt if dt is not None else sentinel
        return (dt2, e.get("id") or "")

    matches.sort(key=_sort_key, reverse=reverse)

    total = len(matches)
    page = matches[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"off:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    # Summaries
    items = []
    for e in page:
        items.append({
            "id": e.get("id"),
            "mail_account_id": e.get("mail_account_id"),
            "provider_message_id": e.get("provider_message_id"),
            "internet_message_id": e.get("internet_message_id"),
            "thread_id": e.get("thread_id"),
            "direction": e.get("direction"),
            "folder_id": e.get("folder_id"),
            "from_name": e.get("from_name"),
            "from_email": e.get("from_email"),
            "to_emails": e.get("to_emails"),
            "cc_emails": e.get("cc_emails"),
            "bcc_emails": e.get("bcc_emails"),
            "subject": e.get("subject"),
            "snippet": e.get("snippet"),
            "has_attachments": e.get("has_attachments"),
            "is_read": e.get("is_read"),
            "received_at": e.get("received_at"),
            "sent_at": e.get("sent_at"),
            "status": e.get("status"),
            "created_at": e.get("created_at"),
            "updated_at": e.get("updated_at"),
        })

    _log("ok")
    return {
        "items": items,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None,
            "total": total,
            "offset": offset
        }
    }

