        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "has_attachments must be a boolean when provided.")
    if status is not None and status not in ("active", "deleted", "purged"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted, purged.")
    if sort_by is None:
        sort_by = "received_at"
    if sort_by not in ("received_at", "sent_at", "created_at", "updated_at"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_by must be one of: received_at, sent_at, created_at, updated_at.")
    if sort_order is None:
        sort_order = "desc"
    if sort_order not in ("asc", "desc"):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string when provided.")

    accounts = _load("mail_accounts.json")
    acct = next((a for a in accounts if a.get("id") == mail_account_id), None)
    if not acct:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Mail account not found.")
    if acct.get("status") != "active":
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Mail account is not active.")

    folders = _load("mail_folders.json")
    if folder_id is not None:
        folder = next((f for f in folders if f.get("id") == folder_id and f.get("mail_account_id") == mail_account_id), None)
        if not folder:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Folder not found in this mail account.")

    # Decode cursor (offset-based)
    offset = 0
    if cursor:
        import base64
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("badcursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("badcursor")
        except Exception:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.")

    def _dt(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    emails = _load("emails.json")
    rows = []
    for e in emails:
        if e.get("mail_account_id") != mail_account_id:
            continue
        # Business rule: listEmails returns status='active' typically; allow filter but default excludes non-active.
        if status is None:
            if e.get("status") != "active":
                continue
        else:
            if e.get("status") != status:
                continue
        if folder_id is not None and e.get("folder_id") != folder_id:
            continue
        if direction is not None and e.get("direction") != direction:
            continue
        if is_read is not None and e.get("is_read") is not is_read:
            continue
        if has_attachments is not None and e.get("has_attachments") is not has_attachments:
            continue
        rows.append(e)

    reverse = (sort_order == "desc")
    def _sort_key(e):
        dt = _dt(e.get(sort_by))
        sentinel = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if reverse else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
        dt2 = dt if dt is not None else sentinel
        return (dt2, e.get("id") or "")

    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_cursor = None
    if offset + limit < total:
        next_cursor = base64.urlsafe_b64encode(f"off:{offset+limit}".encode("utf-8")).decode("utf-8").rstrip("=")

    items = []
    for e in page:
        items.append({
            "id": e.get("id"),
            "mail_account_id": e.get("mail_account_id"),
            "provider_message_id": e.get("provider_message_id"),
            "internet_message_id": e.get("internet_message_id"),
            "thread_id": e.get("thread_id"),
            "direction": e.get("direction"),
            "folder_id": e.get("folder_id"),
            "from_name": e.get("from_name"),
            "from_email": e.get("from_email"),
            "to_emails": e.get("to_emails"),
            "cc_emails": e.get("cc_emails"),
            "bcc_emails": e.get("bcc_emails"),
            "subject": e.get("subject"),
            "snippet": e.get("snippet"),
            "has_attachments": e.get("has_attachments"),
            "is_read": e.get("is_read"),
            "received_at": e.get("received_at"),
            "sent_at": e.get("sent_at"),
            "status": e.get("status"),
            "created_at": e.get("created_at"),
            "updated_at": e.get("updated_at"),
        })

    _log("ok")
    return {
        "items": items,
        "pagination": {
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None,
            "total": total,
            "offset": offset
        }
    }

