            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("off:"):
                raise ValueError("badcursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError("badcursor")
        except Exception:
            _log("error", "VALIDATION_ERROR")
