            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return None

    q = query.strip().lower() if isinstance(query, str) and query.strip() else None

    contacts = _load("contacts.json")
    rows = []
    for c in contacts:
        if c.get("mail_account_id") != mail_account_id:
