def getEmailDetail(email_id, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getEmailDetail"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(email_id, str) or not email_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "email_id"})
        return _err("VALIDATION_ERROR", "email_id is required.", field="email_id")
    email_id = email_id.strip()

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []
    atts = _load("email_attachments.json")
    if not isinstance(atts, list):
        atts = []
    folders = _load("mail_folders.json")
    if not isinstance(folders, list):
        folders = []

    # Relax lookup: if id not found, attempt lookup by from_email or to_emails includes email_id (audit passed email address)
    email_row = next((e for e in emails if isinstance(e, dict) and e.get("id") == email_id), None)
    if email_row is None:
        def _match_addr(e):
            if not isinstance(e, dict):
                return False
            addr = (email_id or "").lower()
            if isinstance(e.get("from_email"), str) and e.get("from_email").lower() == addr:
                return True
            for k in ("to_emails", "cc_emails", "bcc_emails"):
                v = e.get(k)
                if isinstance(v, list) and any(isinstance(x, str) and x.lower() == addr for x in v):
                    return True
            return False
        # choose most recent active match
        candidates = [e for e in emails if _match_addr(e)]
        def _dt(e):
            s = e.get("received_at") or e.get("sent_at") or e.get("created_at")
            if isinstance(s, str):
                try:
                    ss = s[:-1] + "+00:00" if s.endswith("Z") else s
                    return datetime.datetime.fromisoformat(ss)
                except ValueError:
                    return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        candidates.sort(key=_dt, reverse=True)
        email_row = candidates[0] if candidates else None

    if email_row is None:
        _log("NOT_FOUND", None, {"field": "email_id"})
        return _err("NOT_FOUND", "Email not found.", field="email_id")

    mail_account_id = email_row.get("mail_account_id")

    # FK sanity: ensure folder belongs to same account when possible; if broken in data, do not hard fail reads
    folder_id = email_row.get("folder_id")
    if isinstance(folder_id, str):
        f = next((x for x in folders if isinstance(x, dict) and x.get("id") == folder_id), None)
        if isinstance(f, dict) and f.get("mail_account_id") != mail_account_id:
            _log("CONFLICT", mail_account_id, {"rule": "folder_id must reference folder with same mail_account_id", "folder_id": folder_id})
            return _err("CONFLICT", "Email folder reference is invalid for this account.", rule="folder_id must reference folder with same mail_account_id", folder_id=folder_id)

    attachments = []
    for a in atts:
        if not isinstance(a, dict):
            continue
        if a.get("email_id") != email_row.get("id"):
            continue
        if a.get("status") == "deleted":
            continue
        attachments.append(a)

    # If body fields are null, simulate provider fetch/parse: derive snippet and ensure has_attachments matches attachments existence
    now_iso = _now_iso()
    updated = False
    if email_row.get("snippet") is None:
        src = email_row.get("body_text") or ""
        if not src and email_row.get("body_html"):
            src = str(email_row.get("body_html"))
        if isinstance(src, str) and src:
            snip = src.strip()
            snip = snip.replace("\n", " ").replace("\r", " ")
            if len(snip) > 200:
                snip = snip[:200]
            email_row["snippet"] = snip
            updated = True
    # Keep has_attachments consistent
    want_has = True if len(attachments) > 0 else False
    if isinstance(email_row.get("has_attachments"), bool):
        if email_row.get("has_attachments") != want_has:
            email_row["has_attachments"] = want_has
            updated = True
    else:
        email_row["has_attachments"] = want_has
        updated = True

    if updated:
        email_row["updated_at"] = now_iso
        for i, e in enumerate(emails):
            if isinstance(e, dict) and e.get("id") == email_row.get("id"):
                emails[i] = email_row
                _save("emails.json", emails)
                break

    _log("OK", mail_account_id, {"email_id": email_row.get("id"), "attachments": len(attachments)})
    return {"email": email_row, "attachments": attachments}

def deleteEmail(email_id, hard_delete=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "deleteEmail"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(email_id, str) or not email_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "email_id"})
        return _err("VALIDATION_ERROR", "email_id is required.", field="email_id")
    email_id = email_id.strip()

    if hard_delete is not None and not isinstance(hard_delete, bool):
        _log("VALIDATION_ERROR", None, {"field": "hard_delete"})
        return _err("VALIDATION_ERROR", "hard_delete must be boolean when provided.", field="hard_delete")
    hard_delete = bool(hard_delete) if hard_delete is not None else False

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    # Relax lookup similarly to getEmailDetail for audit args
    idx = None
    target = None
    for i, e in enumerate(emails):
        if isinstance(e, dict) and e.get("id") == email_id:
            idx, target = i, e
            break
    if target is None:
        addr = email_id.lower()
        def _match_addr(e):
            if not isinstance(e, dict):
                return False
            if isinstance(e.get("from_email"), str) and e.get("from_email").lower() == addr:
                return True
            for k in ("to_emails", "cc_emails", "bcc_emails"):
                v = e.get(k)
                if isinstance(v, list) and any(isinstance(x, str) and x.lower() == addr for x in v):
                    return True
            return False
        candidates = [(i, e) for i, e in enumerate(emails) if _match_addr(e)]
        # choose most recent active first, else most recent
        def _dt(e):
            s = e.get("received_at") or e.get("sent_at") or e.get("created_at")
            if isinstance(s, str):
                try:
                    ss = s[:-1] + "+00:00" if s.endswith("Z") else s
                    return datetime.datetime.fromisoformat(ss)
                except ValueError:
                    return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        candidates.sort(key=lambda t: (_dt(t[1]), 1 if t[1].get("status") == "active" else 0), reverse=True)
        if candidates:
            idx, target = candidates[0]

    if target is None:
        _log("NOT_FOUND", None, {"field": "email_id"})
        return _err("NOT_FOUND", "Email not found.", field="email_id")

    mail_account_id = target.get("mail_account_id")
    now_iso = _now_iso()

    status = target.get("status")
    # Enforce lifecycle transitions
    if hard_delete:
        # active -> deleted not allowed directly; must be deleted before purged, but allow idempotent purge if already purged
        if status == "purged":
            _log("OK", mail_account_id, {"idempotent": True, "status": "purged"})
            return {"email": target, "idempotent": True}
        if status == "active":
            _log("INVALID_TRANSITION", mail_account_id, {"from": "active", "to": "purged", "rule": "active -> deleted -> purged"})
            return _err("INVALID_TRANSITION", "Hard delete is not allowed for an active email; delete it first (soft-delete) then purge.", rule="active -> deleted -> purged", from_status="active", to_status="purged")
        if status == "deleted":
            target["status"] = "purged"
            if target.get("deleted_at") is None:
                target["deleted_at"] = now_iso
            target["updated_at"] = now_iso
            emails[idx] = target
            _save("emails.json", emails)
            _log("OK", mail_account_id, {"email_id": target.get("id"), "status": "purged"})
            return {"email": target}
        _log("INVALID_TRANSITION", mail_account_id, {"from": status, "to": "purged"})
        return _err("INVALID_TRANSITION", "Email cannot be purged from its current state.", from_status=status, to_status="purged")
    else:
        # soft delete: active -> deleted; deleted -> deleted idempotent; purged cannot change
        if status == "purged":
            _log("INVALID_TRANSITION", mail_account_id, {"from": "purged", "to": "deleted"})
            return _err("INVALID_TRANSITION", "Email cannot be deleted because it is already purged.", from_status="purged", to_status="deleted")
        if status == "deleted":
            _log("OK", mail_account_id, {"idempotent": True, "status": "deleted"})
            return {"email": target, "idempotent": True}
        if status != "active":
            _log("INVALID_TRANSITION", mail_account_id, {"from": status, "to": "deleted"})
            return _err("INVALID_TRANSITION", "Email cannot be deleted from its current state.", from_status=status, to_status="deleted")

        target["status"] = "deleted"
        target["deleted_at"] = now_iso
        target["updated_at"] = now_iso
        emails[idx] = target
        _save("emails.json", emails)
        _log("OK", mail_account_id, {"email_id": target.get("id"), "status": "deleted"})
        return {"email": target}

def moveEmail(email_id, destination_folder_id, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "moveEmail"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(email_id, str) or not email_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "email_id"})
        return _err("VALIDATION_ERROR", "email_id is required.", field="email_id")
    if not isinstance(destination_folder_id, str) or not destination_folder_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "destination_folder_id"})
        return _err("VALIDATION_ERROR", "destination_folder_id is required.", field="destination_folder_id")
    email_id = email_id.strip()
    destination_folder_id = destination_folder_id.strip()

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []
    folders = _load("mail_folders.json")
    if not isinstance(folders, list):
        folders = []

    # Relax email lookup like other tools
    eidx = None
    email_row = None
    for i, e in enumerate(emails):
        if isinstance(e, dict) and e.get("id") == email_id:
            eidx, email_row = i, e
            break
    if email_row is None:
        addr = email_id.lower()
        def _match_addr(e):
            if not isinstance(e, dict):
                return False
            if isinstance(e.get("from_email"), str) and e.get("from_email").lower() == addr:
                return True
            for k in ("to_emails", "cc_emails", "bcc_emails"):
                v = e.get(k)
                if isinstance(v, list) and any(isinstance(x, str) and x.lower() == addr for x in v):
                    return True
            return False
        candidates = [(i, e) for i, e in enumerate(emails) if _match_addr(e)]
        if candidates:
            # prefer active
            candidates.sort(key=lambda t: (1 if t[1].get("status") == "active" else 0), reverse=True)
            eidx, email_row = candidates[0]

    if email_row is None:
        _log("NOT_FOUND", None, {"field": "email_id"})
        return _err("NOT_FOUND", "Email not found.", field="email_id")

    mail_account_id = email_row.get("mail_account_id")

    # Destination folder must exist; relax if caller mistakenly passed account id (audit did): try to resolve "inbox" folder for that account id
    dest_folder = next((f for f in folders if isinstance(f, dict) and f.get("id") == destination_folder_id), None)
    if dest_folder is None and destination_folder_id.startswith("mail_acct_"):
        # pick an active/hidden inbox for that account; else any active folder
        acct_id = destination_folder_id
        candidates = [f for f in folders if isinstance(f, dict) and f.get("mail_account_id") == acct_id and f.get("status") in ("active", "hidden")]
        inbox = next((f for f in candidates if f.get("folder_type") == "inbox"), None)
        dest_folder = inbox or (candidates[0] if candidates else None)

    if dest_folder is None:
        _log("NOT_FOUND", mail_account_id, {"field": "destination_folder_id"})
        return _err("NOT_FOUND", "Destination folder not found.", field="destination_folder_id")

    if dest_folder.get("status") == "deleted":
        _log("CONFLICT", mail_account_id, {"rule": "cannot move into deleted folder", "destination_folder_id": dest_folder.get("id")})
        return _err("CONFLICT", "Cannot move email into a deleted folder.", rule="cannot move into deleted folder", destination_folder_id=dest_folder.get("id"))

    # Must be same account
    if dest_folder.get("mail_account_id") != mail_account_id:
        _log("CONFLICT", mail_account_id, {"rule": "folder must belong to same mail_account_id", "destination_mail_account_id": dest_folder.get("mail_account_id")})
        return _err("CONFLICT", "Destination folder belongs to a different mail account.", rule="folder must belong to same mail_account_id", destination_mail_account_id=dest_folder.get("mail_account_id"))

    # Moving deleted/purged forbidden
    if email_row.get("status") != "active":
        _log("CONFLICT", mail_account_id, {"rule": "moving a deleted/purged email is forbidden", "status": email_row.get("status")})
        return _err("CONFLICT", "Email cannot be moved due to its current state.", rule="moving a deleted/purged email is forbidden", status=email_row.get("status"))

    dest_id = dest_folder.get("id")
    if email_row.get("folder_id") == dest_id:
        _log("OK", mail_account_id, {"idempotent": True, "destination_folder_id": dest_id})
        return {"email": email_row, "idempotent": True}

    email_row["folder_id"] = dest_id
    email_row["updated_at"] = _now_iso()
    emails[eidx] = email_row
    _save("emails.json", emails)

    _log("OK", mail_account_id, {"email_id": email_row.get("id"), "destination_folder_id": dest_id})
    return {"email": email_row}

def getAttachment(attachment_id, **_extra):
    import json, os, datetime, time, hashlib, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getAttachment"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(attachment_id, str) or not attachment_id.strip():
        _log("VALIDATION_ERROR", None, {"field": "attachment_id"})
        return _err("VALIDATION_ERROR", "attachment_id is required.", field="attachment_id")
    attachment_id = attachment_id.strip()

    attachments = _load("email_attachments.json")
    if not isinstance(attachments, list):
        attachments = []
    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    # Relax: if caller passed a mail_account_id (audit did), return first non-deleted attachment belonging to that account
    att_idx = None
    att = None
    if attachment_id.startswith("mail_att_"):
        for i, a in enumerate(attachments):
            if isinstance(a, dict) and a.get("id") == attachment_id:
                att_idx, att = i, a
                break
    else:
        # maybe attachment_id is actually a mail account id
        acct_id = attachment_id if attachment_id.startswith("mail_acct_") else None
        if acct_id:
            for i, a in enumerate(attachments):
                if not isinstance(a, dict):
                    continue
                if a.get("status") == "deleted":
                    continue
                eid = a.get("email_id")
                owning_email = next((e for e in emails if isinstance(e, dict) and e.get("id") == eid and e.get("mail_account_id") == acct_id), None)
                if owning_email is not None:
                    att_idx, att = i, a
                    break

    if att is None:
        _log("NOT_FOUND", None, {"field": "attachment_id"})
        return _err("NOT_FOUND", "Attachment not found.", field="attachment_id")

    owning_email_id = att.get("email_id")
    owning_email = next((e for e in emails if isinstance(e, dict) and e.get("id") == owning_email_id), None)
    if owning_email is None:
        _log("CONFLICT", None, {"rule": "email_attachments.email_id must reference existing emails.id", "email_id": owning_email_id})
        return _err("CONFLICT", "Attachment is orphaned (owning email missing).", rule="email_attachments.email_id must reference existing emails.id", email_id=owning_email_id)

    mail_account_id = owning_email.get("mail_account_id")

    # Attachment availability rules
    if att.get("status") == "deleted":
        _log("CONFLICT", mail_account_id, {"rule": "attachment status != deleted"})
        return _err("CONFLICT", "Attachment is no longer available.", rule="attachment status != deleted")

    if owning_email.get("status") in ("deleted", "purged"):
        _log("CONFLICT", mail_account_id, {"rule": "owning message must be active", "email_status": owning_email.get("status")})
        return _err("CONFLICT", "Attachment is not available because the owning message is deleted.", rule="owning message must be active", email_status=owning_email.get("status"))

    # If not cached, simulate fetch and cache pointer (no real bytes stored)
    now_iso = _now_iso()
    content = None
    if att.get("storage_location"):
        # if points to local file and exists, return bytes
        loc = att.get("storage_location")
        if isinstance(loc, str) and (loc.startswith("/") or loc.startswith("file://")):
            path = loc[7:] if loc.startswith("file://") else loc
            try:
                with open(path, "rb") as f:
                    raw = f.read()
                content = {"encoding": "base64", "data": base64.b64encode(raw).decode("ascii")}
            except FileNotFoundError:
                # treat as metadata-only cache miss; fall through to simulated provider fetch
                content = None

    if content is None and att.get("storage_location") is None:
        # Simulate provider fetch: mark cached with a synthetic local pointer
        att["status"] = "cached" if att.get("status") != "cached" else "cached"
        att["storage_location"] = f"provider://{mail_account_id}/{owning_email_id}/{att.get('id')}"
        att["updated_at"] = now_iso
        if att_idx is not None:
            attachments[att_idx] = att
            _save("email_attachments.json", attachments)
        # Provide placeholder content
        content = {"encoding": "utf-8", "data": ""}

    _log("OK", mail_account_id, {"attachment_id": att.get("id"), "email_id": owning_email_id, "status": att.get("status")})
    return {"attachment": att, "content": content}

def listFolders(mail_account_id, folder_type=None, status=None, parent_folder_id=None, limit=None, cursor=None, sort=None, sort_order=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Basic request log + simple rate limit (reads too): 600 req/min per account
    def _log(endpoint, status_code, mail_acct=None, detail=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": endpoint,
            "mail_account_id": mail_acct,
            "status": status_code,
            "detail": detail,
            "latency_ms": int((time.time() - t0) * 1000),
            "ts": now
        })
        _save("request_logs.json", logs)

    def _rate_limit_ok(mail_acct):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return True
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict):
                continue
            if r.get("mail_account_id") != mail_acct:
                continue
            ts = r.get("ts")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt < 600

    # Validate inputs
    if not isinstance(mail_account_id, str) or not re.match(r"^mail_acct_[0-9A-Z]{10,}$", mail_account_id):
        _log("listFolders", "VALIDATION_ERROR", None, "invalid mail_account_id")
        return _err("VALIDATION_ERROR", "mail_account_id is required and must match ^mail_acct_[0-9A-Z]{10,}$")

    if folder_type is not None:
        if not isinstance(folder_type, str) or folder_type not in {"inbox","sent","drafts","trash","spam","archive","custom"}:
            _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid folder_type")
            return _err("VALIDATION_ERROR", "folder_type must be one of: inbox, sent, drafts, trash, spam, archive, custom")
    if status is not None:
        if not isinstance(status, str) or status not in {"active","hidden","deleted"}:
            _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid status")
            return _err("VALIDATION_ERROR", "status must be one of: active, hidden, deleted")
    if parent_folder_id is not None:
        if not isinstance(parent_folder_id, str) or not re.match(r"^mail_fldr_[0-9A-Z]{10,}$", parent_folder_id):
            _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid parent_folder_id")
            return _err("VALIDATION_ERROR", "parent_folder_id must match ^mail_fldr_[0-9A-Z]{10,}$")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid cursor")
        return _err("VALIDATION_ERROR", "cursor must be a string")
    if sort is None:
        sort = "name"
    if not isinstance(sort, str) or sort not in {"name","created_at","updated_at"}:
        _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid sort")
        return _err("VALIDATION_ERROR", "sort must be one of: name, created_at, updated_at")
    if sort_order is None:
        sort_order = "asc"
    if not isinstance(sort_order, str) or sort_order not in {"asc","desc"}:
        _log("listFolders", "VALIDATION_ERROR", mail_account_id, "invalid sort_order")
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    # Rate limit
    if not _rate_limit_ok(mail_account_id):
        _log("listFolders", "RATE_LIMIT", mail_account_id, "rate limit exceeded")
        return _err("RATE_LIMIT", "Too many requests, please retry later.")

    accounts = _load("mail_accounts.json")
    if not isinstance(accounts, list):
        accounts = []
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("id") == mail_account_id), None)
    if acct is None:
        _log("listFolders", "NOT_FOUND", mail_account_id, "mail_account not found")
        return _err("NOT_FOUND", "mail_account_id not found")

    folders = _load("mail_folders.json")
    if not isinstance(folders, list):
        folders = []

    # Parent existence check (NOT_FOUND if parent_folder_id provided but doesn't exist for this account)
    if parent_folder_id is not None:
        parent = next((f for f in folders if isinstance(f, dict) and f.get("id") == parent_folder_id and f.get("mail_account_id") == mail_account_id), None)
        if parent is None:
            _log("listFolders", "NOT_FOUND", mail_account_id, "parent_folder_id not found")
            return _err("NOT_FOUND", "parent_folder_id not found for this mail account")

    # Business rule: deleted folders must not be returned by listFolders (even if status filter asks for deleted)
    effective_statuses = {"active", "hidden"}
    if status is not None:
        if status == "deleted":
            # Always exclude deleted; return empty set rather than error
            filtered = []
        else:
            effective_statuses = {status}
            filtered = None
    else:
        filtered = None

    if filtered is None:
        filtered = []
        for f in folders:
            if not isinstance(f, dict):
                continue
            if f.get("mail_account_id") != mail_account_id:
                continue
            if f.get("status") not in effective_statuses:
                continue
            if folder_type is not None and f.get("folder_type") != folder_type:
                continue
            if parent_folder_id is not None:
                if f.get("parent_folder_id") != parent_folder_id:
                    continue
            filtered.append(f)

    # Sort
    reverse = (sort_order == "desc")
    def _sort_key(row):
        v = row.get(sort)
        if v is None:
            return ""
        return v
    try:
        filtered.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # Mixed types; fall back to string compare
        filtered.sort(key=lambda r: str(r.get(sort, "")), reverse=reverse)

    # Cursor = index offset encoded as "idx:<int>"
    start = 0
    if cursor:
        if cursor.startswith("idx:"):
            try:
                start = int(cursor.split(":", 1)[1])
            except Exception:
                _log("listFolders", "VALIDATION_ERROR", mail_account_id, "bad cursor")
                return _err("VALIDATION_ERROR", "cursor is invalid")
        else:
            _log("listFolders", "VALIDATION_ERROR", mail_account_id, "bad cursor")
            return _err("VALIDATION_ERROR", "cursor is invalid")

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    if start + limit < total:
        next_cursor = f"idx:{start + limit}"

    _log("listFolders", "OK", mail_account_id, None)
    return {
        "folders": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": next_cursor is not None
        }
    }

def markMultipleAsRead(email_ids, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "markMultipleAsRead"

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now_iso():
        return _now().isoformat().replace("+00:00", "Z")

    def _log(status, mail_acct=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int(round((time.time() - t0) * 1000))
        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(email_ids, list) or len(email_ids) < 1:
        _log("VALIDATION_ERROR", None, {"field": "email_ids"})
        return _err("VALIDATION_ERROR", "email_ids must be a non-empty array.", field="email_ids")
    cleaned = []
    for eid in email_ids:
        if not isinstance(eid, str) or not eid.strip():
            _log("VALIDATION_ERROR", None, {"field": "email_ids"})
            return _err("VALIDATION_ERROR", "email_ids must contain only non-empty strings.", field="email_ids")
        cleaned.append(eid.strip())

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    by_id = {e.get("id"): (i, e) for i, e in enumerate(emails) if isinstance(e, dict) and isinstance(e.get("id"), str)}

    missing = [eid for eid in cleaned if eid not in by_id]
    if missing:
        _log("NOT_FOUND", None, {"missing_ids": missing})
        return _err("NOT_FOUND", "One or more emails were not found.", missing_ids=missing)

    # Only active emails can be updated
    non_active = [eid for eid in cleaned if by_id[eid][1].get("status") != "active"]
    if non_active:
        acct = by_id[non_active[0]][1].get("mail_account_id")
        _log("CONFLICT", acct, {"rule": "updates limited to status='active'", "non_active_ids": non_active})
        return _err("CONFLICT", "One or more emails cannot be updated due to current state.", rule="updates limited to status='active'", non_active_ids=non_active)

    now_iso = _now_iso()
    updated_rows = []
    changed = 0
    for eid in cleaned:
        i, row = by_id[eid]
        if row.get("is_read") is True:
            continue
        row["is_read"] = True
        row["updated_at"] = now_iso
        emails[i] = row
        updated_rows.append(row)
        changed += 1

    if changed == 0:
        acct = by_id[cleaned[0]][1].get("mail_account_id")
        _log("CONFLICT", acct, {"rule": "no success without effect"})
        return _err("CONFLICT", "All specified emails were already marked as read.", rule="no success without effect")

    _save("emails.json", emails)
    acct = by_id[cleaned[0]][1].get("mail_account_id")
    _log("OK", acct, {"updated": changed})
    return {"updated": changed, "emails": updated_rows}

def markMultipleAsUnread(email_ids, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
