        rid = "req_" + hashlib.sha256((endpoint + "|" + _now_iso() + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:16]
        row = {"id": rid, "endpoint": endpoint, "mail_account_id": mail_acct, "status": status, "latency_ms": latency_ms, "timestamp": _now_iso()}
        if meta is not None:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(email_ids, list) or len(email_ids) < 1:
        _log("VALIDATION_ERROR", None, {"field": "email_ids"})
        return _err("VALIDATION_ERROR", "email_ids must be a non-empty array.", field="email_ids")
    cleaned = []
    for eid in email_ids:
        if not isinstance(eid, str) or not eid.strip():
            _log("VALIDATION_ERROR", None, {"field": "email_ids"})
            return _err("VALIDATION_ERROR", "email_ids must contain only non-empty strings.", field="email_ids")
        cleaned.append(eid.strip())

    emails = _load("emails.json")
    if not isinstance(emails, list):
        emails = []

    by_id = {e.get("id"): (i, e) for i, e in enumerate(emails) if isinstance(e, dict) and isinstance(e.get("id"), str)}

    missing = [eid for eid in cleaned if eid not in by_id]
    if missing:
        _log("NOT_FOUND", None, {"missing_ids": missing})
        return _err("NOT_FOUND", "One or more emails were not found.", missing_ids=missing)

    non_active = [eid for eid in cleaned if by_id[eid][1].get("status") != "active"]
    if non_active:
        acct = by_id[non_active[0]][1].get("mail_account_id")
        _log("CONFLICT", acct, {"rule": "updates limited to status='active'", "non_active_ids": non_active})
        return _err("CONFLICT", "One or more emails cannot be updated due to current state.", rule="updates limited to status='active'", non_active_ids=non_active)

    now_iso = _now_iso()
    updated_rows = []
    changed = 0
    for eid in cleaned:
        i, row = by_id[eid]
        if row.get("is_read") is False:
            continue
        row["is_read"] = False
        row["updated_at"] = now_iso
        emails[i] = row
        updated_rows.append(row)
        changed += 1

    if changed == 0:
        acct = by_id[cleaned[0]][1].get("mail_account_id")
        _log("CONFLICT", acct, {"rule": "no success without effect"})
        return _err("CONFLICT", "All specified emails were already marked as unread.", rule="no success without effect")

    _save("emails.json", emails)
    acct = by_id[cleaned[0]][1].get("mail_account_id")
    _log("OK", acct, {"updated": changed})
    return {"updated": changed, "emails": updated_rows}

