def listMailAccounts(status=None, provider=None, email_address=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0336000" if __import__("os").path.isdir("./environment_mix/0336000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "listMailAccounts"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _log(status_s, error=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_s,
            "timestamp": _now_iso(),
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate pagination/sort
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "Invalid limit.", field="limit", minimum=1, maximum=200)
        _log("error", err["error"])
        return err

    if sort is None:
        sort = "created_at_desc"
    if sort not in ("created_at_desc", "created_at_asc", "updated_at_desc", "updated_at_asc"):
        err = _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
        _log("error", err["error"])
        return err

    # Validate filters
    if status is not None:
        if not isinstance(status, list) or any((not isinstance(s, str) or s not in ("active", "disabled", "error")) for s in status):
            err = _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
            _log("error", err["error"])
            return err
    if provider is not None:
        # Note: tool enum says "google" but datastore uses "gmail"; accept both by mapping.
        if not isinstance(provider, list) or any((not isinstance(p, str) or p not in ("google", "microsoft", "imap_smtp", "other")) for p in provider):
            err = _err("VALIDATION_ERROR", "Invalid provider filter.", field="provider")
            _log("error", err["error"])
            return err
    if email_address is not None and (not isinstance(email_address, str) or email_address.strip() == ""):
        err = _err("VALIDATION_ERROR", "Invalid email_address filter.", field="email_address")
        _log("error", err["error"])
        return err

    # Decode cursor
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            err = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _log("error", err["error"])
            return err
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("offset"), int) or obj["offset"] < 0:
                raise ValueError("bad cursor")
            offset = obj["offset"]
        except Exception:
            err = _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")
            _log("error", err["error"])
            return err

    accounts = _load("mail_accounts.json")
    if not isinstance(accounts, list):
        err = _err("CONFLICT", "Datastore corrupted.")
        _log("error", err["error"])
        return err

    # Ambient auth: if there is at least one visible account, caller is effectively authenticated.
    # If none exist, treat as unauthenticated/unauthorized for this service.
    if len(accounts) == 0:
        err = _err("UNAUTHORIZED", "Caller is not authenticated or has no visible mail accounts.")
        _log("error", err["error"])
        return err

    prov_map = {"google": "gmail", "microsoft": "microsoft", "imap_smtp": "imap_smtp", "other": "other"}
    prov_set = None
    if provider is not None:
        prov_set = set(prov_map[p] for p in provider)

    def _norm_email(x):
        return x.strip().lower()

    rows = []
    for a in accounts:
        if not isinstance(a, dict):
            continue
        if status is not None and a.get("status") not in set(status):
            continue
        if prov_set is not None and a.get("provider") not in prov_set:
            continue
        if email_address is not None:
            if not isinstance(a.get("email_address"), str) or _norm_email(a.get("email_address")) != _norm_email(email_address):
                continue
        rows.append(a)

    def _dt_key(val):
        # ISO strings sort lexicographically when consistent; treat missing as empty.
        return val if isinstance(val, str) else ""

    if sort == "created_at_desc":
        rows.sort(key=lambda r: _dt_key(r.get("created_at")), reverse=True)
    elif sort == "created_at_asc":
        rows.sort(key=lambda r: _dt_key(r.get("created_at")), reverse=False)
    elif sort == "updated_at_desc":
        rows.sort(key=lambda r: _dt_key(r.get("updated_at")), reverse=True)
    else:  # updated_at_asc
        rows.sort(key=lambda r: _dt_key(r.get("updated_at")), reverse=False)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    resp = {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    _log("ok", meta={"returned": len(page), "total": total, "offset": offset})
    return resp

