            "latency_ms": int((time.time() - t0) * 1000),
        }
        if meta is not None:
            row["meta"] = meta
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate required id
    if not isinstance(mail_account_id, str) or not re.match(r"^mail_acct_[0-9A-HJKMNP-TV-Z]{10,}$", mail_account_id):
        err = _err("VALIDATION_ERROR", "Invalid mail_account_id.", field="mail_account_id")
        _log("error", err["error"])
