        _log("error", err["error"])
        return err
    if smtp_port is not None and (not isinstance(smtp_port, int) or smtp_port < 1 or smtp_port > 65535):
        err = _err("VALIDATION_ERROR", "Invalid smtp_port.", field="smtp_port", minimum=1, maximum=65535)
        _log("error", err["error"])
        return err

    # Ensure at least one mutable field provided
    if all(v is None for v in (display_name, default_from_name, status, imap_host, imap_port, smtp_host, smtp_port)):
        err = _err("VALIDATION_ERROR", "No fields to update.")
        _log("error", err["error"])
