    # Lifecycle transitions
    transitions = {
        "active": set(["disabled", "error"]),
        "disabled": set(["active"]),
        "error": set(["active", "disabled"]),
    }

    new_acct = dict(acct)
    if status is not None and status != acct.get("status"):
