        if v is not None and (not isinstance(v, int) or v < 1 or v > 65535):
            err = _err("VALIDATION_ERROR", f"Invalid {k}.", field=k, minimum=1, maximum=65535)
            _log("error", err["error"], meta={"mail_account_id": mail_account_id})
            return err
    if auth_type in ("oauth2", "api_key"):
        if new_acct.get("auth_secret_ref") in (None, ""):
            err = _err("VALIDATION_ERROR", "auth_secret_ref is required for this auth_type.", field="auth_secret_ref")
            _log("error", err["error"], meta={"mail_account_id": mail_account_id})
            return err

    # Unique(email_address, provider)
    ea = new_acct.get("email_address")
    prov = new_acct.get("provider")
    for a in accounts:
        if not isinstance(a, dict) or a.get("id") == mail_account_id:
            continue
        if a.get("email_address") == ea and a.get("provider") == prov:
            err = _err("CONFLICT", "A mail account with this email_address and provider already exists.",
                       email_address=ea, provider=prov)
            _log("error", err["error"], meta={"mail_account_id": mail_account_id})
            return err

    # Persist update
    new_acct["updated_at"] = _now_iso()
    accounts[idx] = new_acct
    _save("mail_accounts.json", accounts)

    resp = {"data": new_acct}
    _log("ok", meta={"mail_account_id": mail_account_id})
    return resp
